  addText(orig, fmtSigned(C) + 'y² = 1', 462, 100, 10.5, '#222', 'start', false);

  var rot = card(452, 326, state.rotatedEquation, 'Rotated x′,y′');
  rot.rect(40, 17).move(462, 351).radius(3).fill(state.rotatedEquation ? '#d9ecff' : '#f4f4f4').stroke('none');
  addText(rot, 'x′²/' + majorA.toFixed(2) + '² +', 466, 350, 10.5, blue, 'start', false);
  rot.rect(40, 17).move(462, 373).radius(3).fill(state.rotatedEquation ? '#d9ecff' : '#f4f4f4').stroke('none');
