var origin = { x: 245, y: 225 };
var sc = 61;
var majorA = 2.75;
var minorB = 1.32;
var blue = '#173f78';
var orange = '#f05a24';
var black = '#111111';

function toScreen(wx, wy) {
  return [origin.x + sc * wx, origin.y - sc * wy];
}

function toWorld(sx, sy) {
  return [(sx - origin.x) / sc, (origin.y - sy) / sc];
}

function pointsAttr(arr) {
  return arr.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' ');
}

function addArrow(g, x1, y1, x2, y2, color, width, both) {
  g.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' });
  var dx = x2 - x1, dy = y2 - y1;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / len, uy = dy / len;
  var px = -uy, py = ux;
  var headL = 12, headW = 8;
  function head(tx, ty, dir) {
    var bx = tx - dir * ux * headL;
    var by = ty - dir * uy * headL;
    g.polygon([
      [tx, ty],
      [bx + px * headW / 2, by + py * headW / 2],
      [bx - px * headW / 2, by - py * headW / 2]
    ]).fill(color).stroke('none');
  }
  head(x2, y2, 1);
  if (both) head(x1, y1, -1);
}

function addText(g, str, x, y, size, color, anchor, italic) {
  return g.text(str)
    .move(x, y)
    .font({
      family: italic ? 'Georgia, Times, serif' : 'Arial, sans-serif',
      size: size,
      anchor: anchor || 'start',
      style: italic ? 'italic' : 'normal'
    })
    .fill(color)
    .attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
}

function screenFromLocal(xp, yp, th) {
  var c = Math.cos(th), s = Math.sin(th);
  return toScreen(xp * c - yp * s, xp * s + yp * c);
}

function localFromWorld(wx, wy, th) {
  var c = Math.cos(th), s = Math.sin(th);
  return {
    xp: wx * c + wy * s,
    yp: -wx * s + wy * c
  };
}

