<!-- @FIGURE_UI_BEGIN -->
<label>Rotation angle θ: <output id="thetaRotationVal">45</output><input id="thetaRotationInput" type="range" min="0" max="90" step="1" value="45" oninput="document.getElementById('thetaRotationVal').value=this.value;update_thetaRotation(+this.value)"></label>
