<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 600, H = 450;
draw.viewbox(0, 0, W, H);

var state = {
  thetaDeg: 45,
  rotatedEquation: false,
  showEquationCards: false,
  showPoint: false,
  pointT: 5.05
};

var currentStep = 0;
var demoSteps = [
  {
    title: 'See the tilted conic in the original frame',
    narration: 'The black x and y axes stay fixed while the ellipse is tilted across them. In this original coordinate system, the xy term appears because the conic is not aligned with the axes.',
    state: { thetaRotation: 45, equationView: 'Original x,y equation' }
  },
  {
    title: 'Rotate the coordinate frame',
    narration: 'Drag θ and watch the orange x′ and y′ axes turn with the ellipse while the black axes remain fixed. The alignment is best when x′ follows the long axis of the ellipse.',
    state: { thetaRotation: 45, equationView: 'Original x,y equation' }
  },
  {
    title: 'Compare equation forms',
    narration: 'Switch to the rotated equation: the highlight moves away from the xy cross term. In the x′,y′ frame, the ellipse is described by squared terms only.',
    state: { thetaRotation: 45, equationView: 'Rotated x′,y′ equation' }
  },
  {
    title: 'Compare coordinates of one point',
    narration: 'A selected point on the ellipse is the same geometric point, but its coordinate pair changes depending on whether it is measured with the black axes or the orange axes.',
    state: { thetaRotation: 45, equationView: 'Rotated x′,y′ equation' }
  }
];

var origin = { x: 260, y: 230 };
var sc = 78;
var majorA = 2.9;
var minorB = 1.4;
var blue = '#173f78';
var orange = '#f05a24';
var black = '#111111';

function toScreen(wx, wy) {
  return [origin.x + sc * wx, origin.y - sc * wy];
}

function toWorld(sx, sy) {
  return [(sx - origin.x) / sc, (origin.y - sy) / sc];
}

function pointsAttr(arr) {
  return arr.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' ');
}

function addArrow(g, x1, y1, x2, y2, color, width, both) {
  g.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' });
  var dx = x2 - x1, dy = y2 - y1;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / len, uy = dy / len;
  var px = -uy, py = ux;
  var headL = color === orange ? 14 : 10;
  var headW = color === orange ? 9 : 7;
  function head(tx, ty, dir) {
    var bx = tx - dir * ux * headL;
    var by = ty - dir * uy * headL;
    g.polygon([
      [tx, ty],
      [bx + px * headW / 2, by + py * headW / 2],
      [bx - px * headW / 2, by - py * headW / 2]
    ]).fill(color).stroke('none');
  }
  head(x2, y2, 1);
  if (both) head(x1, y1, -1);
}

function addText(g, str, x, y, size, color, anchor, italic) {
  return g.text(str)
    .move(x, y)
    .font({
      family: italic ? 'Georgia, Times, serif' : 'Arial, sans-serif',
      size: size,
      anchor: anchor || 'start',
      style: italic ? 'italic' : 'normal'
    })
    .fill(color)
    .attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
}

function screenFromLocal(xp, yp, th) {
  var c = Math.cos(th), s = Math.sin(th);
  return toScreen(xp * c - yp * s, xp * s + yp * c);
}

function localFromWorld(wx, wy, th) {
  var c = Math.cos(th), s = Math.sin(th);
  return {
    xp: wx * c + wy * s,
    yp: -wx * s + wy * c
  };
}

function eventPoint(evt) {
  var pt = draw.node.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  return pt.matrixTransform(draw.node.getScreenCTM().inverse());
}

function fmtCoeff(n) {
  var sign = n < 0 ? '−' : '+';
  return sign + Math.abs(n).toFixed(2);
}

function drawAxes(root, th) {
  var fixed = root.group();

  addArrow(fixed, 34, origin.y, 535, origin.y, black, 1.15, true);
  addArrow(fixed, origin.x, 428, origin.x, 20, black, 1.15, true);

  addText(fixed, 'x', 547, origin.y + 19, 19, black, 'middle', true);
  addText(fixed, 'y', origin.x + 1, 0, 19, black, 'middle', true);

  fixed.on('mousemove', function (e) {
    showTooltip('The black x and y axes are the fixed original coordinate system.', e);
  }).on('mouseleave', hideTooltip);
  fixed.css('cursor', 'pointer');

  var rot = root.group();
  var c = Math.cos(th), s = Math.sin(th);
  var L = 3.68;

  var p1 = toScreen(-L * c, -L * s);
  var p2 = toScreen(L * c, L * s);
  var q1 = toScreen(L * s, -L * c);
  var q2 = toScreen(-L * s, L * c);

  addArrow(rot, p1[0], p1[1], p2[0], p2[1], orange, 2.3, true);
  addArrow(rot, q1[0], q1[1], q2[0], q2[1], orange, 2.3, true);

  var xl = toScreen((L + 0.11) * c, (L + 0.11) * s);
  var yl = toScreen(-(L + 0.10) * s, (L + 0.10) * c);

  addText(rot, 'x′', xl[0] - 2, xl[1] - 24, 18, orange, 'middle', true);
  addText(rot, 'y′', yl[0] + 12, yl[1] - 16, 18, orange, 'middle', true);

  rot.on('mousemove', function (e) {
    showTooltip('The orange axes are the rotated x′ and y′ frame, sharing the same origin as x and y.', e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('Rotated axes', 'Only the measuring directions have changed. When x′ and y′ follow the ellipse’s own axes, the cross-product term can disappear.');
  });
  rot.css('cursor', 'pointer');
}

function drawEllipse(root, th) {
  var pts = [];
  for (var i = 0; i <= 260; i++) {
    var t = 2 * Math.PI * i / 260;
    pts.push(screenFromLocal(majorA * Math.cos(t), minorB * Math.sin(t), th));
  }

  var line = root.polyline(pointsAttr(pts)).fill('none')
    .stroke({ color: blue, width: 3.1, linecap: 'round', linejoin: 'round' });

  var hit = root.polyline(pointsAttr(pts)).fill('none')
    .stroke({ color: '#ffffff', width: 20, opacity: 0.001, linecap: 'round', linejoin: 'round' });

  line.on('mousemove', function (e) {
    showTooltip('This is one fixed ellipse, elongated along the orange x′ direction.', e);
  }).on('mouseleave', hideTooltip);
  line.css('cursor', 'pointer');

  hit.on('mousemove', function (e) {
    showTooltip('Click the ellipse to reveal one point and compare its coordinates in the two frames.', e);
  }).on('mouseleave', hideTooltip).on('click', function (e) {
    var p = eventPoint(e);
    var w = toWorld(p.x, p.y);
    var loc = localFromWorld(w[0], w[1], th);
    state.pointT = Math.atan2(loc.yp / minorB, loc.xp / majorA);
    state.showPoint = true;
    render();
    showPopup('Same point, different coordinates', 'The selected point did not move. Its coordinate values change because the black and orange axes measure the same location in different directions.');
  });
  hit.css('cursor', 'pointer');
}

function drawAngleArc(root, th) {
  var g = root.group();
  var r = 0.67;
  var pts = [];
  var steps = Math.max(6, Math.round(Math.max(1, state.thetaDeg) / 4));
  for (var i = 0; i <= steps; i++) {
    var a = th * i / steps;
    pts.push(toScreen(r * Math.cos(a), r * Math.sin(a)));
  }
  g.polyline(pointsAttr(pts)).fill('none').stroke({ color: black, width: 1.25, linecap: 'round' });

  if (state.thetaDeg > 7) {
    var last = pts[pts.length - 1];
    var prev = pts[pts.length - 2];
    addArrow(g, prev[0], prev[1], last[0], last[1], black, 1.05, false);
  }

  var mid = th / 2;
  var lab = toScreen(0.92 * Math.cos(mid), 0.92 * Math.sin(mid));
  addText(g, 'θ', lab[0] + 2, lab[1] - 9, 18, black, 'start', true);

  g.on('mousemove', function (e) {
    showTooltip('θ is the angle from the positive x-axis to the positive x′-axis.', e);
  }).on('mouseleave', hideTooltip);
  g.css('cursor', 'pointer');
}

function drawEquationCards(root, th) {
  if (!state.showEquationCards) return;

  var g = root.group();
  var c = Math.cos(th), s = Math.sin(th);
  var invA = 1 / (majorA * majorA);
  var invB = 1 / (minorB * minorB);
  var A = c * c * invA + s * s * invB;
  var Bxy = 2 * c * s * (invA - invB);
  var C = s * s * invA + c * c * invB;

  function card(x, y, w, h, active, title) {
    var cg = g.group();
    cg.rect(w, h).move(x, y).radius(7)
      .fill(active ? '#fff8dc' : '#ffffff')
      .stroke({ color: active ? '#e2b84a' : '#d7d7d7', width: active ? 1.25 : 1 })
      .opacity(active ? 0.98 : 0.55);
    addText(cg, title, x + 9, y + 7, 10.5, '#333333', 'start', false).attr({ stroke: '#fff', 'stroke-width': 2 });
    return cg;
  }

  var ox = 444, oy = 90;
  var orig = card(ox, oy, 130, 66, !state.rotatedEquation, 'Original x,y');
  addText(orig, A.toFixed(2) + 'x²', ox + 10, oy + 29, 10.5, '#222222', 'start', false).attr({ stroke: '#fff', 'stroke-width': 2 });
  orig.rect(44, 17).move(ox + 55, oy + 28).radius(3)
    .fill(!state.rotatedEquation ? '#ffe773' : '#eeeeee').stroke('none');
  addText(orig, fmtCoeff(Bxy) + 'xy', ox + 60, oy + 29, 10.5, '#b14a00', 'start', false).attr({ stroke: '#fff', 'stroke-width': 2 });
  addText(orig, fmtCoeff(C) + 'y² = 1', ox + 10, oy + 50, 10.5, '#222222', 'start', false).attr({ stroke: '#fff', 'stroke-width': 2 });

  var rx = 444, ry = 300;
  var rot = card(rx, ry, 130, 76, state.rotatedEquation, 'Rotated x′,y′');
  rot.rect(52, 17).move(rx + 10, ry + 28).radius(3)
    .fill(state.rotatedEquation ? '#d9ecff' : '#eeeeee').stroke('none');
  addText(rot, 'x′²/' + majorA.toFixed(1) + '² +', rx + 14, ry + 29, 10.5, blue, 'start', false).attr({ stroke: '#fff', 'stroke-width': 2 });
  rot.rect(52, 17).move(rx + 10, ry + 49).radius(3)
    .fill(state.rotatedEquation ? '#d9ecff' : '#eeeeee').stroke('none');
  addText(rot, 'y′²/' + minorB.toFixed(1) + '² = 1', rx + 14, ry + 50, 10.5, blue, 'start', false).attr({ stroke: '#fff', 'stroke-width': 2 });
  addText(rot, 'no x′y′ term', rx + 10, ry + 68, 9.8, orange, 'start', false).attr({ stroke: '#fff', 'stroke-width': 2 });

  g.on('mousemove', function (e) {
    showTooltip('The original equation has an xy term; the aligned rotated equation has no x′y′ term.', e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('Two equations for one curve', 'The ellipse itself is unchanged. Rotating the axes changes the coordinate description, and in the aligned frame the cross term is removed.');
  });
  g.css('cursor', 'pointer');
}

function drawPointAndProjections(root, th) {
  if (!state.showPoint) return;

  var g = root.group();
  var xp = majorA * Math.cos(state.pointT);
  var yp = minorB * Math.sin(state.pointT);
  var c = Math.cos(th), s = Math.sin(th);
  var wx = xp * c - yp * s;
  var wy = xp * s + yp * c;
  var P = toScreen(wx, wy);

  var Fx = toScreen(wx, 0);
  var Fy = toScreen(0, wy);
  g.line(P[0], P[1], Fx[0], Fx[1]).stroke({ color: black, width: 1.15, dasharray: '5,4', opacity: 0.62 });
  g.line(P[0], P[1], Fy[0], Fy[1]).stroke({ color: black, width: 1.15, dasharray: '5,4', opacity: 0.62 });

  var footXp = toScreen(xp * c, xp * s);
  var footYp = toScreen(-yp * s, yp * c);
  g.line(P[0], P[1], footXp[0], footXp[1]).stroke({ color: orange, width: 1.45, dasharray: '6,4', opacity: 0.75 });
  g.line(P[0], P[1], footYp[0], footYp[1]).stroke({ color: orange, width: 1.45, dasharray: '6,4', opacity: 0.75 });

  g.circle(5).center(Fx[0], Fx[1]).fill('#ffffff').stroke({ color: black, width: 1 });
  g.circle(5).center(Fy[0], Fy[1]).fill('#ffffff').stroke({ color: black, width: 1 });
  g.circle(5).center(footXp[0], footXp[1]).fill('#ffffff').stroke({ color: orange, width: 1.15 });
  g.circle(5).center(footYp[0], footYp[1]).fill('#ffffff').stroke({ color: orange, width: 1.15 });

  var dot = g.circle(12).center(P[0], P[1]).fill('#ffffff').stroke({ color: blue, width: 3 });
  dot.on('mousemove', function (e) {
    showTooltip('This is the same point measured in two coordinate systems.', e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('Coordinate comparison', 'Black dashed segments measure the point with x and y. Orange dashed segments measure the same point with x′ and y′.');
  });
  dot.css('cursor', 'pointer');

  var bx = P[0] < 350 ? P[0] + 18 : P[0] - 150;
  var by = P[1] < 110 ? P[1] + 18 : P[1] - 62;
  bx = Math.max(22, Math.min(430, bx));
  by = Math.max(42, Math.min(370, by));

  g.rect(136, 43).move(bx - 6, by - 5).radius(5).fill('#ffffff').opacity(0.92).stroke({ color: '#dddddd', width: 1 });
  addText(g, '(x, y) = (' + wx.toFixed(2) + ', ' + wy.toFixed(2) + ')', bx, by, 10.2, black, 'start', false).attr({ stroke: '#fff', 'stroke-width': 2 });
  addText(g, '(x′, y′) = (' + xp.toFixed(2) + ', ' + yp.toFixed(2) + ')', bx, by + 19, 10.2, orange, 'start', false).attr({ stroke: '#fff', 'stroke-width': 2 });
}

function render() {
  draw.clear();
  draw.rect(W, H).fill('#ffffff');
  var th = state.thetaDeg * Math.PI / 180;

  drawAxes(draw, th);
  drawEllipse(draw, th);
  drawAxes(draw, th);
  drawAngleArc(draw, th);
  drawPointAndProjections(draw, th);
  drawEquationCards(draw, th);
}

function update_thetaRotation(v) {
  state.thetaDeg = v;
  render();
}

function toggle_equationView(on) {
  state.rotatedEquation = !!on;
  state.showEquationCards = true;
  render();
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];

  state.thetaDeg = step.state.thetaRotation;
  state.rotatedEquation = step.state.equationView === 'Rotated x′,y′ equation';
  state.showEquationCards = currentStep >= 2;
  state.showPoint = currentStep >= 3;

  var slider = document.getElementById('thetaRotationInput');
  var out = document.getElementById('thetaRotationVal');
  var check = document.getElementById('equationViewInput');
  if (slider) slider.value = state.thetaDeg;
  if (out) out.value = state.thetaDeg;
  if (check) check.checked = state.rotatedEquation;

  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/4 ' + step.title;

  render();
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

